INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (148, 23, '5', 5, 'calculation', 12.00, '计算 \(I=\oint_\Gamma(3y-x)\,dx-5z\,dz\)，其中 \(\Gamma\) 为 \(x^2+y^2+z^2=8\) 与 \(x^2+y^2=2z\) 的交线，从 \(z\) 轴正向看取逆时针方向。', '\(I=0\)。', '联立得 \(z=2,x^2+y^2=4\)。取 \(x=2\cos t,y=2\sin t,z=2\) 代入一周积分即得。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 计算 (I= (3y-x) ,dx-5z ,dz )，其中 ( ) 为 (x 2+y 2+z 2=8 ) 与 (x 2+y 2=2z ) 的交线，从 (z ) 轴正向看取逆时针方向。 (I=0 )。 联立得 (z=2,x 2+y 2=4 )。取 (x=2 t,y=2 t,z=2 ) 代入一周积分即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (149, 23, '6', 6, 'proof', 12.00, '定义 \(\displaystyle f(n)=\sum_{m=1}^n\int_0^m\cos\frac{2\pi n[x+1]}m\,dx\)。证明 \(f(n)\) 等于 \(n\) 的所有正因子之和，并计算 \(f(2021)\)。', '\(f(n)=\sigma(n)\)，且 \(f(2021)=2112\)。', '把积分按单位区间分割成单位根之和：当 \(m\mid n\) 时为 \(m\)，否则为 0。又 \(2021=43\times47\)，故 \((1+43)(1+47)=2112\)。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 定义 ( f(n)= m=1 n 0 m 2 n[x+1] m ,dx )。证明 (f(n) ) 等于 (n ) 的所有正因子之和，并计算 (f(2021) )。 (f(n)= (n) )，且 (f(2021)=2112 )。 把积分按单位区间分割成单位根之和：当 (m n ) 时为 (m )，否则为 0。又 (2021=43 47 )，故 ((1+43)(1+47)=2112 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (150, 23, '7', 7, 'comprehensive', 14.00, '设 \(\displaystyle u_n=\int_0^1\frac{dt}{(1+t^4)^n}\)。\n\n1. 证明 \(u_n\) 收敛并求极限；\n2. 证明 \(\sum_{n=1}^\infty(-1)^nu_n\) 条件收敛；\n3. 证明 \(p\ge1\) 时 \(\sum u_n/n^p\) 收敛，并求 \(\sum u_n/n\)。', '1. \(u_n\to0\)。 2. 级数条件收敛。 3. 对所有 \(p\ge1\) 收敛，且\n\[\sum_{n=1}^\infty\frac{u_n}{n}=\ln2+\frac{\sqrt2}{2}\left[\pi+2\ln(1+\sqrt2)\right].\]', '分段夹逼得 \(u_n\to0\)；由单调性用 Leibniz 判别，另以调和级数作下界证非绝对收敛。分部积分得 \(u_n/n=1/(n2^n)+4(u_n-u_{n+1})\)，求和并代入 \(u_1\) 即得。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 设 ( u n= 0 1 dt (1+t 4) n )。 1. 证明 (u n ) 收敛并求极限； 2. 证明 ( n=1 (-1) nu n ) 条件收敛； 3. 证明 (p 1 ) 时 ( u n/n p ) 收敛，并求 ( u n/n )。 1. (u n 0 )。 2. 级数条件收敛。 3. 对所有 (p 1 ) 收敛，且 [ n=1 u n n = 2+ 2 2 [ +2 (1+ 2) ]. ] 分段夹逼得 (u n 0 )；由单调性用 Leibniz 判别，另以调和级数作下界证非绝对收敛。分部积分得 (u n/n=1/(n2 n)+4(u n-u n+1 ) )，求和并代入 (u 1 ) 即得。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (151, 24, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac{k}{n^2}\sin^2\left(1+\frac{k}{n}\right)\)。\n2. \(u=xyz+e^{xyz}\)，求其在 \(P_0(1,1,-1)\) 沿 \(P_0P_1\)（\(P_1=(2,-1,0)\)）方向的方向导数。\n3. \(\Gamma:x^2+y^2+z^2=a^2,x+y+z=0\)，求 \(\displaystyle\oint_\Gamma(1+x)^2ds\)。\n4. 三阶矩阵 \(A\) 满足 \(|A^*|=16,|A|>0\)，且 \(ABA^{-1}=BA^{-1}+3I\)，求 \(B\)。\n5. \(u=x_1+x_2/x_1+x_3/x_2+2/x_3\ (x_i>0)\)，求全部极值点。', '1. \(\displaystyle\frac{2-2\sin4-\cos4+\cos2}{8}\)。\n2. \(\displaystyle\frac{2(1+e^{-1})}{\sqrt6}\)。 3. \(\displaystyle2\pi a(1+a^2/3)\)。\n4. \(\displaystyle B=3(I-A^{-1})^{-1}=3(I-A^*/4)^{-1}\)。\n5. 唯一极值点 \(\displaystyle(2^{1/4},2^{1/2},2^{3/4})\)，为极小值点。', '1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 \(x,y,z\) 的对称性。\n4. 由 \(|A^*|=|A|^2\) 得 \(|A|=4\)，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( n k=1 n k n 2 2 (1+ k n ) )。 2. (u=xyz+e xyz )，求其在 (P 0(1,1,-1) ) 沿 (P 0P 1 )（ (P 1=(2,-1,0) )）方向的方向导数。 3. ( :x 2+y 2+z 2=a 2,x+y+z=0 )，求 ( (1+x) 2ds )。 4. 三阶矩阵 (A ) 满足 (|A *|=16,|A|>0 )，且 (ABA -1 =BA -1 +3I )，求 (B )。 5. (u=x 1+x 2/x 1+x 3/x 2+2/x 3 (x i>0) )，求全部极值点。 1. ( 2-2 4- 4+ 2 8 )。 2. ( 2(1+e -1 ) 6 )。 3. ( 2 a(1+a 2/3) )。 4. ( B=3(I-A -1 ) -1 =3(I-A */4) -1 )。 5. 唯一极值点 ( (2 1/4 ,2 1/2 ,2 3/4 ) )，为极小值点。 1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 (x,y,z ) 的对称性。 4. 由 (|A *|=|A| 2 ) 得 (|A|=4 )，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (152, 24, '2', 2, 'calculation', 12.00, '设 \(n\) 为正整数，求\n\[\lim_{x\to0}\frac{\displaystyle\prod_{k=1}^n\left(\frac{1+kx}{1-kx}\right)^{1/(2k)}-1}{3\pi\arcsin x-(1+x^2)\arctan^3x}.\]', '\(\displaystyle\frac{n}{3\pi}\)。', '记乘积为 \(f(x)\)，对数求导得 \(f(0)=1,f''(0)=n\)。分母等价于 \(3\pi x\)，故极限为 \(n/(3\pi)\)。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (n ) 为正整数，求 [ x 0 k=1 n ( 1+kx 1-kx ) 1/(2k) -1 3 x-(1+x 2) 3x . ] ( n 3 )。 记乘积为 (f(x) )，对数求导得 (f(0)=1,f''(0)=n )。分母等价于 (3 x )，故极限为 (n/(3 ) )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (153, 24, '3', 3, 'calculation', 12.00, '求幂级数 \(\displaystyle\sum_{n=1}^\infty[1-n\ln(1+1/n)]x^n\) 的收敛域。', '\([-1,1)\)。', '系数 \(a_n\sim1/(2n)\)，故半径为 1。\(x=1\) 发散；\(x=-1\) 时由 Leibniz 判别法收敛。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 求幂级数 ( n=1 [1-n (1+1/n)]x n ) 的收敛域。 ([-1,1) )。 系数 (a n 1/(2n) )，故半径为 1。 (x=1 ) 发散； (x=-1 ) 时由 Leibniz 判别法收敛。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (154, 24, '4', 4, 'proof', 12.00, '设 \(f\) 在 \([a,b]\) 连续、在 \((a,b)\) 二阶可导，且 \(f(a)=f(b)=0\)、\(\int_a^bf(x)dx=0\)。证明存在不同的 \(x_1,x_2\) 使 \(f''(x_i)=f(x_i)\)，并存在不同于二者的 \(\xi\) 使 \(f''''(\xi)=f(\xi)\)。', '所述 \(x_1,x_2,\xi\) 均存在。', '依次对 \(e^{-x}\int_a^xf\)、\(f(x)-\int_a^xf\) 和 \(e^x[f''(x)-f(x)]\) 使用 Rolle 定理。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (f ) 在 ([a,b] ) 连续、在 ((a,b) ) 二阶可导，且 (f(a)=f(b)=0 )、 ( a bf(x)dx=0 )。证明存在不同的 (x 1,x 2 ) 使 (f''(x i)=f(x i) )，并存在不同于二者的 ( ) 使 (f''''( )=f( ) )。 所述 (x 1,x 2, ) 均存在。 依次对 (e -x a xf )、 (f(x)- a xf ) 和 (e x[f''(x)-f(x)] ) 使用 Rolle 定理。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (155, 24, '5', 5, 'comprehensive', 12.00, '设 \(A\) 是 \(n\) 阶实对称矩阵。证明存在唯一实对称矩阵 \(B\)，使 \(B^{2021}=A\)、\(AB=BA\)，且存在多项式 \(p\) 使 \(B=p(A)\)。', '所述实对称奇次方根存在、可表示为 \(p(A)\)，且唯一。', '正交对角化 \(A\)，对每个实特征值取唯一实 2021 次根构造 \(B\)；用 Lagrange 插值构造 \(p\)。标量奇次根唯一给出矩阵解唯一。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (A ) 是 (n ) 阶实对称矩阵。证明存在唯一实对称矩阵 (B )，使 (B 2021 =A )、 (AB=BA )，且存在多项式 (p ) 使 (B=p(A) )。 所述实对称奇次方根存在、可表示为 (p(A) )，且唯一。 正交对角化 (A )，对每个实特征值取唯一实 2021 次根构造 (B )；用 Lagrange 插值构造 (p )。标量奇次根唯一给出矩阵解唯一。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (156, 24, '6', 6, 'proof', 12.00, '设 \(A_n(x,y)=\sum_{k=0}^nx^{n-k}y^k\)，\(0<x,y<1\)。证明\n\[\frac2{2-x-y}\le\sum_{n=0}^\infty\frac{A_n(x,y)}{n+1}\le\frac12\left(\frac1{1-x}+\frac1{1-y}\right).\]', '所给双边不等式成立。', '逐项证明 \(((x+y)/2)^n\le A_n/(n+1)\le(x^n+y^n)/2\)，再对 \(n\) 求和。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (A n(x,y)= k=0 nx n-k y k )， (0<x,y<1 )。证明 [ 2 2-x-y n=0 A n(x,y) n+1 12 ( 1 1-x + 1 1-y ). ] 所给双边不等式成立。 逐项证明 (((x+y)/2) n A n/(n+1) (x n+y n)/2 )，再对 (n ) 求和。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (157, 24, '7', 7, 'proof', 10.00, '设 \(f,g:[0,1]\to[0,1]\) 连续，且 \(f\) 单调增加。证明\n\[\int_0^1f(g(x))dx\le\int_0^1f(x)dx+\int_0^1g(x)dx.\]', '所给积分不等式成立。', '令 \(F(x)=f(x)-x\)，估计 \(\max F-\int_0^1F\le1/2\)，代入 \(F(g(x))\) 并整理即得。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (f,g:[0,1] [0,1] ) 连续，且 (f ) 单调增加。证明 [ 0 1f(g(x))dx 0 1f(x)dx+ 0 1g(x)dx. ] 所给积分不等式成立。 令 (F(x)=f(x)-x )，估计 ( F- 0 1F 1/2 )，代入 (F(g(x)) ) 并整理即得。', 6, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (131, 21, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{x\to0}\frac{\ln(e^{\sin x}+\sqrt[3]{1-\cos x})-\sin x}{\arctan(4\sqrt[3]{1-\cos x})}\)。\n2. 曲线 \(y^2(x-y)=x^2\)，求 \(\displaystyle\int\frac{dx}{y^2}\)。\n3. 求 \(\displaystyle\int_0^{\pi/2}\frac{e^x(1+\sin x)}{(1+\cos x)^2}\,dx\)。\n4. 求全微分 \(\displaystyle du=\frac{y\,dx-x\,dy}{3x^2-2xy+3y^2}\) 的原函数。\n5. 曲面 \(xyz=\mu\) 与椭球 \(x^2/a^2+y^2/b^2+z^2/c^2=1\) 相切，求 \(\mu\)。', '1. \(1/4\)。 2. \(\displaystyle3y/x-2\ln|y/x|+C\)。 3. \(e^{\pi/2}\)。\n4. \(\displaystyle u=\frac1{2\sqrt2}\arctan\left[\frac3{2\sqrt2}\left(\frac{x}{y}-\frac13\right)\right]+C\)。\n5. \(\displaystyle\mu=\frac{abc}{3\sqrt3}\)。', '1. 展开分子分母的最低阶项。 2. 利用隐式关系令 \(u=y/x\) 化为可积形式。\n3. 识别为 \(e^x/(1+\cos x)\) 的导数。 4. 令 \(t=x/y\) 后积分。\n5. 用 Lagrange 乘子或 AM-GM 求椭球上 \(xyz\) 的极值。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x 0 (e x + [3] 1- x )- x (4 [3] 1- x ) )。 2. 曲线 (y 2(x-y)=x 2 )，求 ( dx y 2 )。 3. 求 ( 0 /2 e x(1+ x) (1+ x) 2 ,dx )。 4. 求全微分 ( du= y ,dx-x ,dy 3x 2-2xy+3y 2 ) 的原函数。 5. 曲面 (xyz= ) 与椭球 (x 2/a 2+y 2/b 2+z 2/c 2=1 ) 相切，求 ( )。 1. (1/4 )。 2. ( 3y/x-2 |y/x|+C )。 3. (e /2 )。 4. ( u= 1 2 2 [ 3 2 2 ( x y - 13 ) ]+C )。 5. ( = abc 3 3 )。 1. 展开分子分母的最低阶项。 2. 利用隐式关系令 (u=y/x ) 化为可积形式。 3. 识别为 (e x/(1+ x) ) 的导数。 4. 令 (t=x/y ) 后积分。 5. 用 Lagrange 乘子或 AM-GM 求椭球上 (xyz ) 的极值。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (132, 21, '2', 2, 'calculation', 14.00, '计算\n\[\iiint_\Omega\frac{xyz}{x^2+y^2}\,dx\,dy\,dz,\]\n其中 \(\Omega\) 是第一卦限内由 \((x^2+y^2+z^2)^2=2xy\) 围成的区域。', '\(\displaystyle\frac1{72}\)。', '用球坐标 \(x=r\sin\varphi\cos\theta,y=r\sin\varphi\sin\theta,z=r\cos\varphi\)。边界化为 \(r^2=\sin^2\varphi\sin2\theta\)，按第一卦限积分即得 \(1/72\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 计算 [ xyz x 2+y 2 ,dx ,dy ,dz, ] 其中 ( ) 是第一卦限内由 ((x 2+y 2+z 2) 2=2xy ) 围成的区域。 ( 1 72 )。 用球坐标 (x=r ,y=r ,z=r )。边界化为 (r 2= 2 2 )，按第一卦限积分即得 (1/72 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (133, 21, '3', 3, 'proof', 14.00, '设 \(f\) 在 \([0,\infty)\) 可导，\(f(0)=0\)，且存在常数 \(A>0\) 使 \(|f''(x)|\le A|f(x)|\)。证明 \(f(x)\equiv0\)。', '\(f\equiv0\)。', '令 \(F(x)=\int_0^x|f(t)|dt\)，则 \(|f(x)|\le A F(x)\)，从而 \(F''(x)\le AF(x)\)、\(F(0)=0\)。乘以 \(e^{-Ax}\) 后得 \(F\equiv0\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0, ) ) 可导， (f(0)=0 )，且存在常数 (A>0 ) 使 (|f''(x)| A|f(x)| )。证明 (f(x) 0 )。 (f 0 )。 令 (F(x)= 0 x|f(t)|dt )，则 (|f(x)| A F(x) )，从而 (F''(x) AF(x) )、 (F(0)=0 )。乘以 (e -Ax ) 后得 (F 0 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (134, 21, '4', 4, 'calculation', 14.00, '计算\n\[I=\int_0^{2\pi}d\varphi\int_0^\pi e^{\sin\theta(\cos\varphi-\sin\varphi)}\sin\theta\,d\theta.\]', '\(\displaystyle I=\sqrt2\pi(e^{\sqrt2}-e^{-\sqrt2})\)。', '把积分视为单位球面上 \(e^{x-y}\) 的面积分，旋转坐标轴使新极轴沿 \((1,-1,0)\)，化为 \(2\pi\int_0^\pi e^{\sqrt2\cos\alpha}\sin\alpha,d\alpha\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 计算 [I= 0 2 d 0 e ( - ) ,d . ] ( I= 2 (e 2 -e - 2 ) )。 把积分视为单位球面上 (e x-y ) 的面积分，旋转坐标轴使新极轴沿 ((1,-1,0) )，化为 (2 0 e 2 ,d )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (135, 21, '5', 5, 'proof', 14.00, '设多项式 \(f(x)\) 的根全为正实数，并在原点附近展开\n\[-\frac{f''(x)}{f(x)}=\sum_{n=0}^\infty c_nx^n.\]\n证明 \(c_n>0\)，且 \(\displaystyle\lim_{n\to\infty}c_n^{-1/n}\) 等于 \(f\) 的最小正根。', '各 \(c_n>0\)，所给极限等于最小正根。', '若各根为 \(r_j>0\)，则 \(-f''/f=\sum_j1/(r_j-x)=\sum_{n\ge0}(\sum_jr_j^{-n-1})x^n\)。因此系数为正；最大项由最小根控制，取 \(n\) 次根即得结论。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设多项式 (f(x) ) 的根全为正实数，并在原点附近展开 [- f''(x) f(x) = n=0 c nx n. ] 证明 (c n>0 )，且 ( n c n -1/n ) 等于 (f ) 的最小正根。 各 (c n>0 )，所给极限等于最小正根。 若各根为 (r j>0 )，则 (-f''/f= j1/(r j-x)= n 0 ( jr j -n-1 )x n )。因此系数为正；最大项由最小根控制，取 (n ) 次根即得结论。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (136, 21, '6', 6, 'proof', 14.00, '函数 \(f\) 满足\n\[3[3+f^2(x)]f''(x)=2[1+f^2(x)]^2e^{-x^2},\qquad f(0)\le1.\]\n证明 \(f\) 在实轴上有界。', '\(f\) 在 \(\mathbb R\) 上有界。', '分离变量并注意 \(\frac{3(3+u^2)}{2(1+u^2)^2}\) 在无穷远可积，而右端 \(e^{-x^2}\) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 函数 (f ) 满足 [3[3+f 2(x)]f''(x)=2[1+f 2(x)] 2e -x 2 , f(0) 1. ] 证明 (f ) 在实轴上有界。 (f ) 在 ( R ) 上有界。 分离变量并注意 ( 3(3+u 2) 2(1+u 2) 2 ) 在无穷远可积，而右端 (e -x 2 ) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (137, 22, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{x\to\pi/2}\frac{(1-\sqrt{\sin x})(1-\sqrt[3]{\sin x})\cdots(1-\sqrt[n]{\sin x})}{(1-\sin x)^{n-1}}\)。\n2. 曲线 \(3x-y=2\arctan(y-2x)\)，求其在 \(P(1+\pi/2,3+\pi)\) 处切线。\n3. 二次曲线通过 \((-1,0),(0,-1),(0,1),(2,-1),(2,1)\)，求曲线上两点最大距离。\n4. \(f(x)=(x^2+2x-3)^n\arctan^2(x/3)\)，求 \(f^{(n)}(-3)\)。\n5. \(f(0)=f(1)=0\)，且 \(\int_0^1[f''(x)]^2dx-8\int_0^1f(x)dx+4/3=0\)，求 \(f\)。', '1. \(1/n!\)。 2. \(\displaystyle y=\frac52x+\frac12-\frac\pi4\)。 3. \(4\)。\n4. \(\displaystyle(-1)^n4^{n-2}n!\pi^2\)。 5. \(f(x)=2x-2x^2\)。', '1. 每个因子除以 \(1-\sin x\) 后取极限。 2. 隐式求导。\n3. 代入五点得椭圆 \((x-1)^2/4+y^2/(4/3)=1\)。 4. 提取 \((x+3)^n\) 后用 Leibniz 公式。\n5. 分部积分把题设化为 \(\int_0^1[f''(x)+4x-2]^2dx=0\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x /2 (1- x )(1- [3] x ) (1- [n] x ) (1- x) n-1 )。 2. 曲线 (3x-y=2 (y-2x) )，求其在 (P(1+ /2,3+ ) ) 处切线。 3. 二次曲线通过 ((-1,0),(0,-1),(0,1),(2,-1),(2,1) )，求曲线上两点最大距离。 4. (f(x)=(x 2+2x-3) n 2(x/3) )，求 (f (n) (-3) )。 5. (f(0)=f(1)=0 )，且 ( 0 1[f''(x)] 2dx-8 0 1f(x)dx+4/3=0 )，求 (f )。 1. (1/n! )。 2. ( y= 52x+ 12- 4 )。 3. (4 )。 4. ( (-1) n4 n-2 n! 2 )。 5. (f(x)=2x-2x 2 )。 1. 每个因子除以 (1- x ) 后取极限。 2. 隐式求导。 3. 代入五点得椭圆 ((x-1) 2/4+y 2/(4/3)=1 )。 4. 提取 ((x+3) n ) 后用 Leibniz 公式。 5. 分部积分把题设化为 ( 0 1[f''(x)+4x-2] 2dx=0 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (138, 22, '2', 2, 'calculation', 12.00, '求极限\n\[\lim_{n\to\infty}n\left(1-\sum_{k=1}^n\frac1{\sqrt{n+k}}\right).\]', '\(\displaystyle\frac23\)。', '把差写成 \(\sum_{k=1}^n(1/\sqrt n-1/\sqrt{n+k})\)，有理化后用积分上下和夹逼，极限为 \(2/3\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 求极限 [ n n (1- k=1 n 1 n+k ). ] ( 23 )。 把差写成 ( k=1 n(1/ n-1/ n+k ) )，有理化后用积分上下和夹逼，极限为 (2/3 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (139, 22, '3', 3, 'calculation', 12.00, '设\n\[F(x_1,x_2,x_3)=\int_0^{2\pi}f(x_1+x_3\cos\varphi,x_2+x_3\sin\varphi)\,d\varphi,\]\n其中 \(f\) 有二阶连续偏导数。化简\n\[x_3(F_{x_1x_1}+F_{x_2x_2}-F_{x_3x_3})-F_{x_3}.\]', '\(0\)。', '在积分号下求导。对 \(F_{x_3}\) 中的三角因子关于 \(\varphi\) 分部积分，所得二阶导数组合恰与前项相同，故相减为零。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设 [F(x 1,x 2,x 3)= 0 2 f(x 1+x 3 ,x 2+x 3 ) ,d , ] 其中 (f ) 有二阶连续偏导数。化简 [x 3(F x 1x 1 +F x 2x 2 -F x 3x 3 )-F x 3 . ] (0 )。 在积分号下求导。对 (F x 3 ) 中的三角因子关于 ( ) 分部积分，所得二阶导数组合恰与前项相同，故相减为零。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (140, 22, '4', 4, 'proof', 10.00, '设 \(f\in C^1[0,1]\)，且 \(\int_0^1f(x)dx=5/2\)、\(\int_0^1xf(x)dx=3/2\)。证明存在 \(\xi\in(0,1)\)，使 \(f''(\xi)=3\)。', '所述 \(\xi\) 存在。', '计算 \(\int_0^1x(1-x)[3-f''(x)]dx\)，分部积分并代入两矩条件得零。由积分中值定理且权函数在内部为正，得 \(f''(\xi)=3\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设 (f C 1[0,1] )，且 ( 0 1f(x)dx=5/2 )、 ( 0 1xf(x)dx=3/2 )。证明存在 ( (0,1) )，使 (f''( )=3 )。 所述 ( ) 存在。 计算 ( 0 1x(1-x)[3-f''(x)]dx )，分部积分并代入两矩条件得零。由积分中值定理且权函数在内部为正，得 (f''( )=3 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (141, 22, '5', 5, 'proof', 12.00, '空间 \(\mathbb R^3\) 中有 2021 个半径非零的球 \(B_i\)。令 \(A=(a_{ij})\)，其中 \(a_{ij}\) 为 \(B_i\cap B_j\) 的体积。证明 \(|E+A|>1\)。', '\(|E+A|>1\)。', '把 \(a_{ij}\) 写成两个球的示性函数内积，得 \(A\) 半正定。其特征值均非负，且 \(A\ne0\)，所以至少一个特征值为正，故 \(|E+A|=\prod(1+\lambda_i)>1\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 空间 ( R 3 ) 中有 2021 个半径非零的球 (B i )。令 (A=(a ij ) )，其中 (a ij ) 为 (B i B j ) 的体积。证明 (|E+A|>1 )。 (|E+A|>1 )。 把 (a ij ) 写成两个球的示性函数内积，得 (A ) 半正定。其特征值均非负，且 (A 0 )，所以至少一个特征值为正，故 (|E+A|= (1+ i)>1 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (142, 22, '6', 6, 'proof', 12.00, '设 \(\Omega\) 的边界为光滑闭曲面 \(\Sigma\)，\(f\in C^2(\Omega)\) 且 \(f|_\Sigma=0\)。证明对任意 \(C>0\)，\n\[C\iiint_\Omega f^2dV+\frac1C\iiint_\Omega(\Delta f)^2dV\ge2\iiint_\Omega|\nabla f|^2dV.\]', '所给积分不等式成立。', '由 Green 第一恒等式及边界值为零，\(\int|\nabla f|^2=-\int f\Delta f\)。再对 \(\sqrt C f\) 与 \(\Delta f/\sqrt C\) 用 Cauchy 不等式。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设 ( ) 的边界为光滑闭曲面 ( )， (f C 2( ) ) 且 (f| =0 )。证明对任意 (C>0 )， [C f 2dV+ 1C ( f) 2dV 2 | f| 2dV. ] 所给积分不等式成立。 由 Green 第一恒等式及边界值为零， ( | f| 2=- f f )。再对 ( C f ) 与 ( f/ C ) 用 Cauchy 不等式。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (143, 22, '7', 7, 'comprehensive', 12.00, '设正数列满足\n\[\frac{u_{n+1}}{u_n}=1-\frac\alpha n+O(n^{-\beta}),\qquad\beta>1.\]\n令 \(v_n=n^\alpha u_n\)。证明 \(v_n\) 有正的有限极限，并判断 \(\sum u_n\) 的敛散性。', '\(v_n\to C\in(0,\infty)\)；\(\sum u_n\) 当且仅当 \(\alpha>1\) 时收敛。', '展开 \(\ln(v_{n+1}/v_n)\)，一次项抵消，余项为 \(O(n^{-2})+O(n^{-\beta})\)，其级数绝对收敛，故乘积趋于正有限值。于是 \(u_n\sim Cn^{-\alpha}\)，与 \(p\)-级数比较即得。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设正数列满足 [ u n+1 u n =1- n+O(n - ), >1. ] 令 (v n=n u n )。证明 (v n ) 有正的有限极限，并判断 ( u n ) 的敛散性。 (v n C (0, ) )； ( u n ) 当且仅当 ( >1 ) 时收敛。 展开 ( (v n+1 /v n) )，一次项抵消，余项为 (O(n -2 )+O(n - ) )，其级数绝对收敛，故乘积趋于正有限值。于是 (u n Cn - )，与 (p )-级数比较即得。', 6, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (117, 19, '1', 1, 'calculation', 24.00, '填空题，共 4 小题，每小题 6 分。\n\n1. 设 \(0<\alpha<1\)，求 \(\displaystyle\lim_{n\to\infty}[(n+1)^\alpha-n^\alpha]\)。\n2. 曲线由 \(x=t+\cos t\)、\(e^y+ty+\sin t=1\) 确定，求 \(t=0\) 对应点处的切线。\n3. 求 \(\displaystyle\int\frac{\ln(x+\sqrt{1+x^2})}{(1+x^2)^{3/2}}\,dx\)。\n4. 求 \(\displaystyle\lim_{x\to0}\frac{1-\cos x\,(\cos2x)^{1/2}(\cos3x)^{1/3}}{x^2}\)。', '1. \(0\)。 2. \(y=-x+1\)。\n3. \(\displaystyle\frac{x}{\sqrt{1+x^2}}\ln(x+\sqrt{1+x^2})-\frac12\ln(1+x^2)+C\)。\n4. \(3\)。', '1. 用凹函数估计或令 \(x=1/n\) 化为等价无穷小。\n2. 对参数方程求导，代入 \(t=0,x=1,y=0\)，得斜率 \(-1\)。\n3. 令 \(x=\tan t\) 并分部积分。\n4. 对三个余弦因子作二阶 Taylor 展开，乘积为 \(1-3x^2+o(x^2)\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 填空题，共 4 小题，每小题 6 分。 1. 设 (0< <1 )，求 ( n [(n+1) -n ] )。 2. 曲线由 (x=t+ t )、 (e y+ty+ t=1 ) 确定，求 (t=0 ) 对应点处的切线。 3. 求 ( (x+ 1+x 2 ) (1+x 2) 3/2 ,dx )。 4. 求 ( x 0 1- x ,( 2x) 1/2 ( 3x) 1/3 x 2 )。 1. (0 )。 2. (y=-x+1 )。 3. ( x 1+x 2 (x+ 1+x 2 )- 12 (1+x 2)+C )。 4. (3 )。 1. 用凹函数估计或令 (x=1/n ) 化为等价无穷小。 2. 对参数方程求导，代入 (t=0,x=1,y=0 )，得斜率 (-1 )。 3. 令 (x= t ) 并分部积分。 4. 对三个余弦因子作二阶 Taylor 展开，乘积为 (1-3x 2+o(x 2) )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (118, 19, '2', 2, 'calculation', 8.00, '设 \(f(t)\) 在 \(t\ne0\) 时一阶连续可导，且 \(f(1)=0\)。求 \(f(x^2-y^2)\)，使\n\[\int_Ly[2-f(x^2-y^2)]\,dx+xf(x^2-y^2)\,dy\]\n与路径无关，其中 \(L\) 为任一不与直线 \(y=\pm x\) 相交的分段光滑曲线。', '\(\displaystyle f(x^2-y^2)=1-\frac1{x^2-y^2}\)。', '由 \(P_y=Q_x\) 得 \(uf''(u)+f(u)-1=0\)，其通解为 \(f(u)=1+C/u\)。再由 \(f(1)=0\) 得 \(C=-1\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f(t) ) 在 (t 0 ) 时一阶连续可导，且 (f(1)=0 )。求 (f(x 2-y 2) )，使 [ Ly[2-f(x 2-y 2)] ,dx+xf(x 2-y 2) ,dy ] 与路径无关，其中 (L ) 为任一不与直线 (y= x ) 相交的分段光滑曲线。 ( f(x 2-y 2)=1- 1 x 2-y 2 )。 由 (P y=Q x ) 得 (uf''(u)+f(u)-1=0 )，其通解为 (f(u)=1+C/u )。再由 (f(1)=0 ) 得 (C=-1 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (119, 19, '3', 3, 'proof', 14.00, '设 \(f\) 在 \([0,1]\) 连续，且 \(1\le f(x)\le3\)。证明\n\[1\le\int_0^1f(x)\,dx\int_0^1\frac{dx}{f(x)}\le\frac43.\]', '所给双边不等式成立。', '下界由 Cauchy 不等式。上界利用 \((f-1)(3-f)\ge0\)，即 \(f+3/f\le4\)，积分后结合算术—几何平均不等式即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 连续，且 (1 f(x) 3 )。证明 [1 0 1f(x) ,dx 0 1 dx f(x) 43. ] 所给双边不等式成立。 下界由 Cauchy 不等式。上界利用 ((f-1)(3-f) 0 )，即 (f+3/f 4 )，积分后结合算术—几何平均不等式即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (120, 19, '4', 4, 'calculation', 12.00, '计算 \(\iiint_V(x^2+y^2)\,dV\)，其中 \(V\) 由\n\[x^2+y^2+(z-2)^2\ge4,\quad x^2+y^2+(z-1)^2\le9,\quad z\ge0\]\n所围成。', '\(\displaystyle\frac{256\pi}{3}\)。', '用柱坐标，按两个球面的交圈分段确定 \(r,z\) 的范围；对 \(r^2\cdot r\,dr\,d\theta\,dz\) 积分，得 \(256\pi/3\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 计算 ( V(x 2+y 2) ,dV )，其中 (V ) 由 [x 2+y 2+(z-2) 2 4, x 2+y 2+(z-1) 2 9, z 0 ] 所围成。 ( 256 3 )。 用柱坐标，按两个球面的交圈分段确定 (r,z ) 的范围；对 (r 2 r ,dr ,d ,dz ) 积分，得 (256 /3 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (121, 19, '5', 5, 'proof', 14.00, '设 \(f(x,y)\) 在区域 \(D\) 内可微，且 \(\sqrt{f_x^2+f_y^2}\le M\)。若线段 \(AB\subset D\)，证明\n\[|f(A)-f(B)|\le M|AB|.\]', '所给 Lipschitz 估计成立。', '参数化线段 \(X(t)=A+t(B-A)\)。对 \(f(X(t))\) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 \(M|AB|\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f(x,y) ) 在区域 (D ) 内可微，且 ( f x 2+f y 2 M )。若线段 (AB D )，证明 [|f(A)-f(B)| M|AB|. ] 所给 Lipschitz 估计成立。 参数化线段 (X(t)=A+t(B-A) )。对 (f(X(t)) ) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 (M|AB| )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (122, 19, '6', 6, 'proof', 14.00, '证明对连续函数 \(f(x)>0\)，有\n\[\ln\int_0^1f(x)\,dx\ge\int_0^1\ln f(x)\,dx.\]', '所给 Jensen 不等式成立。', '函数 \(\ln x\) 为凹函数。对积分作等分 Riemann 和并应用有限形式 Jensen 不等式，再令分点数趋于无穷。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 证明对连续函数 (f(x)>0 )，有 [ 0 1f(x) ,dx 0 1 f(x) ,dx. ] 所给 Jensen 不等式成立。 函数 ( x ) 为凹函数。对积分作等分 Riemann 和并应用有限形式 Jensen 不等式，再令分点数趋于无穷。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (123, 19, '7', 7, 'proof', 14.00, '已知正数列 \(\{a_k\},\{b_k\}\) 满足 \(b_{k+1}-b_k\ge\delta>0\)。证明：若 \(\sum_{k=1}^\infty a_k\) 收敛，则\n\[\sum_{k=1}^\infty\frac{\sqrt[k]{(a_1a_2\cdots a_k)(b_1b_2\cdots b_k)}}{b_{k+1}b_k}\]\n收敛。', '所给正项级数收敛。', '令 \(S_k=\sum_{i=1}^ka_ib_i\)。对 \(\sum a_k\) 作 Abel 变换，并用 \(b_{k+1}-b_k\ge\delta\)，可得 \(\sum S_k/(b_kb_{k+1})\) 收敛。又由算术—几何平均不等式，\(\sqrt[k]{\prod_{i=1}^ka_ib_i}\le S_k/k\le S_k\)，比较即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 已知正数列 ( a k , b k ) 满足 (b k+1 -b k >0 )。证明：若 ( k=1 a k ) 收敛，则 [ k=1 [k] (a 1a 2 a k)(b 1b 2 b k) b k+1 b k ] 收敛。 所给正项级数收敛。 令 (S k= i=1 ka ib i )。对 ( a k ) 作 Abel 变换，并用 (b k+1 -b k )，可得 ( S k/(b kb k+1 ) ) 收敛。又由算术—几何平均不等式， ( [k] i=1 ka ib i S k/k S k )，比较即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;